import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.cNy3aYYk.js";const d=JSON.parse('{"title":"Payment Gateways (workspace)","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payment Gateways (workspace) | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/tenant-payment-gateways"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payment Gateways (workspace) | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/tenant-payment-gateways"}]]},"headers":[],"relativePath":"user-guide/tenant-payment-gateways.md","filePath":"user-guide/tenant-payment-gateways.md","lastUpdated":1794259478000}'),r={name:"user-guide/tenant-payment-gateways.md"};function s(i,e,l,c,m,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="payment-gateways-workspace" tabindex="-1">Payment Gateways (workspace) <a class="header-anchor" href="#payment-gateways-workspace" aria-label="Permalink to &quot;Payment Gateways (workspace)&quot;">​</a></h1><p>Connect <strong>your</strong> Stripe, Creem, or Kelviq account so customers can pay unpaid invoices from the Customer Portal. This is separate from EloSync Marketplace billing (Central → Payment Gateways).</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Install <strong>Payments</strong> (required dependency)</li><li>Install <strong>Payment Gateways</strong> from Marketplace (free, not default-included)</li><li>Optional: <strong>Customer Portal</strong> for Pay now</li></ul><p>You need <code>payment-gateways.view</code> to open the page and <code>payment-gateways.manage_integrations</code> to configure gateways (admin/manager by default).</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Marketplace → install <strong>Payment Gateways</strong> (Payments must already be installed).</li><li>Open <strong>Billing → Payment Gateways</strong>.</li><li>For each provider you want: <ul><li><strong>Configure</strong> → paste sandbox/live keys and webhook secret</li><li>Creem also needs an <strong>invoice product ID</strong> (one-time product used with dynamic amount)</li><li>Kelviq also needs an <strong>invoice plan identifier</strong></li><li>Enable the gateway → <strong>Save</strong> → <strong>Test connection</strong></li></ul></li><li>Point the provider’s webhook to the URL shown (or use <strong>Copy webhook URL</strong>).</li><li><strong>Set as default</strong> on one ready gateway (used when the customer does not pick another).</li></ol><p>You can enable <strong>multiple</strong> gateways. Customers see every ready gateway on the portal invoice and can choose; the workspace default is pre-selected.</p><h2 id="portal-pay-now" tabindex="-1">Portal Pay now <a class="header-anchor" href="#portal-pay-now" aria-label="Permalink to &quot;Portal Pay now&quot;">​</a></h2><p>On an unpaid invoice in the Customer Portal:</p><ul><li>One ready gateway → <strong>Pay now</strong></li><li>Several ready gateways → pick a provider, then <strong>Pay now</strong></li></ul><p>Successful checkout posts a gateway payment on the Payments ledger and applies it to the invoice. Payments list <strong>Method</strong> shows the provider name (Stripe, Creem, or Kelviq), not a generic “Gateway” label.</p><h3 id="minimum-charge-amounts" tabindex="-1">Minimum charge amounts <a class="header-anchor" href="#minimum-charge-amounts" aria-label="Permalink to &quot;Minimum charge amounts&quot;">​</a></h3><p>Stripe enforces a minimum online charge. For currencies Stripe publishes (for example USD <strong>0.50</strong>), EloSync blocks Pay now before opening Checkout. For other presentment currencies (for example <strong>PKR</strong>), Stripe may still reject small amounts after converting to your Stripe account’s settlement currency — increase the invoice balance and try again.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Keep sandbox mode until you verify webhooks end-to-end.</li><li>Disconnect clears secrets for that provider only; other gateways stay configured.</li><li>Staff refunds for Stripe-captured payments still use <strong>Refund via Stripe</strong> on the payment record.</li></ul>',16)])])}const y=t(r,[["render",s]]);export{d as __pageData,y as default};
